// 필터 드롭다운 컴포넌트
import { useState, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import './FilterDropdown.css';

interface FilterOption {
  id: string;
  label: string;
  color?: string;
}

interface FilterDropdownProps {
  label: string;
  options: FilterOption[];
  selectedIds: string[];
  onChange: (selectedIds: string[]) => void;
  multiple?: boolean;
  showColorDot?: boolean;
}

export default function FilterDropdown({
  label,
  options,
  selectedIds,
  onChange,
  multiple = true,
  showColorDot = false,
}: FilterDropdownProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [menuPosition, setMenuPosition] = useState({ top: 0, left: 0 });
  const dropdownRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  // 외부 클릭 시 닫기
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as Node;
      // 버튼과 메뉴 모두 외부인 경우에만 닫기
      if (
        dropdownRef.current && !dropdownRef.current.contains(target) &&
        menuRef.current && !menuRef.current.contains(target)
      ) {
        setIsOpen(false);
      }
    };
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [isOpen]);

  // 메뉴 위치 계산
  const updateMenuPosition = () => {
    if (buttonRef.current) {
      const rect = buttonRef.current.getBoundingClientRect();
      setMenuPosition({
        top: rect.bottom + 4,
        left: Math.min(rect.left, window.innerWidth - 180), // 화면 밖으로 나가지 않도록
      });
    }
  };

  const handleToggle = (optionId: string) => {
    if (multiple) {
      if (selectedIds.includes(optionId)) {
        onChange(selectedIds.filter((id) => id !== optionId));
      } else {
        onChange([...selectedIds, optionId]);
      }
    } else {
      onChange([optionId]);
      setIsOpen(false);
    }
  };

  const handleSelectAll = () => {
    if (selectedIds.length === options.length) {
      onChange([]);
    } else {
      onChange(options.map((o) => o.id));
    }
  };

  const getButtonLabel = () => {
    if (selectedIds.length === 0) return `${label}: 전체`;
    if (selectedIds.length === options.length) return `${label}: 전체`;
    if (selectedIds.length === 1) {
      const selected = options.find((o) => o.id === selectedIds[0]);
      return `${label}: ${selected?.label || ''}`;
    }
    return `${label}: ${selectedIds.length}개`;
  };

  return (
    <div className="filter-dropdown" ref={dropdownRef}>
      <button 
        ref={buttonRef}
        className={`filter-btn ${selectedIds.length > 0 && selectedIds.length < options.length ? 'active' : ''}`}
        onClick={() => {
          if (!isOpen) {
            updateMenuPosition();
          }
          setIsOpen(!isOpen);
        }}
      >
        {getButtonLabel()}
        <span className="dropdown-arrow">{isOpen ? '▲' : '▼'}</span>
      </button>

      {isOpen && createPortal(
        <div 
          ref={menuRef}
          className="filter-menu"
          style={{
            position: 'fixed',
            top: menuPosition.top,
            left: menuPosition.left,
            zIndex: 99999,
          }}
        >
          {multiple && (
            <button className="filter-select-all" onClick={handleSelectAll}>
              {selectedIds.length === options.length ? '선택 해제' : '전체 선택'}
            </button>
          )}
          <ul className="filter-options">
            {options.map((option) => (
              <li
                key={option.id}
                className={`filter-option ${selectedIds.includes(option.id) ? 'selected' : ''}`}
                onClick={() => handleToggle(option.id)}
              >
                {showColorDot && option.color && (
                  <span className="filter-color" style={{ backgroundColor: option.color }} />
                )}
                <span className="filter-label">{option.label}</span>
                {multiple && (
                  <span className="filter-check">
                    {selectedIds.includes(option.id) ? '✓' : ''}
                  </span>
                )}
              </li>
            ))}
          </ul>
        </div>,
        document.body
      )}
    </div>
  );
}
